// Replays proto/testdata/settle_vectors.json (generated by
// `cd proto/go && go test ./settle -run TestSettleVectors -update`) against
// proto/ts/src/settle. If this fails, the TS port has drifted from Go — fix the
// divergence rather than regenerating the fixture.

import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { describe, expect, it } from 'vitest'

import { SettleStatus, classify, computeFeeBreakdown, netFee } from '../src/settle/index.js'

type Json = Record<string, any> // eslint-disable-line @typescript-eslint/no-explicit-any

const here = path.dirname(fileURLToPath(import.meta.url))
const v = JSON.parse(fs.readFileSync(path.resolve(here, '..', '..', 'testdata', 'settle_vectors.json'), 'utf8')) as Json

// Go keys statuses by snake_case name; the TS constant uses PascalCase.
const byName: Record<string, number> = {
    unrecognized: SettleStatus.Unrecognized,
    open: SettleStatus.Open,
    pending_payer: SettleStatus.PendingPayer,
    pending_operator: SettleStatus.PendingOperator,
    frozen: SettleStatus.Frozen,
}

describe('settle_vectors.json', () => {
    it('is the schema this test expects', () => {
        expect(v.version).toBe(1)
    })

    // A renamed key in the fixture would otherwise turn a section's loop into
    // zero tests and pass.
    it('has cases in every section', () => {
        for (const section of [v.classify, v.net_fee, v.fee_breakdown]) {
            expect(Array.isArray(section) && section.length > 0).toBe(true)
        }
    })

    it('numbers every status as Go does', () => {
        expect(v.statuses).toEqual(byName)
        expect(Object.keys(SettleStatus).length).toBe(Object.keys(v.statuses).length)
    })

    describe('classify', () => {
        for (const c of v.classify) {
            it(c.name, () => {
                const status = byName[c.status] ?? Number(c.status)
                expect(classify({ status, deadline: BigInt(c.deadline) }, new Date(Number(c.now_unix_ms)))).toBe(
                    c.verdict,
                )
            })
        }
    })

    describe('fees', () => {
        for (const c of v.net_fee) {
            it(`netFee(${c.amount_charged}, ${c.fee_bps}, ${c.discount_bps})`, () => {
                expect(String(netFee(BigInt(c.amount_charged), BigInt(c.fee_bps), BigInt(c.discount_bps)))).toBe(c.want)
                // Ticket records decode the bps as numbers; that path must agree too.
                expect(String(netFee(BigInt(c.amount_charged), Number(c.fee_bps), Number(c.discount_bps)))).toBe(c.want)
            })
        }
        for (const c of v.fee_breakdown) {
            it(`computeFeeBreakdown(${c.amount_charged}, ${c.max_price}, ${c.fee_bps})`, () => {
                const b = computeFeeBreakdown(
                    BigInt(c.amount_charged),
                    BigInt(c.max_price),
                    BigInt(c.fee_bps),
                    BigInt(c.discount_bps),
                )
                expect([b.amountCharged, b.netFee, b.refund, b.totalDebit].map(String)).toEqual([
                    c.amount_charged,
                    c.net_fee,
                    c.refund,
                    c.total_debit,
                ])
            })
        }
    })
})
